examples.code:
mkdir -p disposable
touch disposable/a.tmp disposable/keep.txt
find disposable -type f -name '*.tmp' -exec rm -i -- {} \;

cat > decomposition-entry.txt <<'EOF'
numberOfSubdomains 4;
method scotch;
EOF

demoDir=$(mktemp -d "$HOME/foam-remove.XXXXXX")
mkdir -p "$demoDir"/{trial1,trial2}
for name in trial1 trial2; do removeCase "$demoDir/$name"; done

cat > toy.lyy <<'EOF'
%token_type {double}
%default_type {double}
input ::= NUMBER.
EOF
"$WM_PROJECT_DIR/wmake/scripts/wrap-lemon" -ecc toy.lyy
